class Solution {
public:
    vector<string> letterCombinations(string digits) {
        vector<string> res;                 // 存放所有字母组合
        if (digits.empty()) return res;     // 边界：空输入返回空数组（而非 [""]）
        const vector<string> MAPPING = {"", "", "abc", "def", "ghi",
                                        "jkl", "mno", "pqrs", "tuv", "wxyz"};
        string path;                        // 当前已确定的字母前缀
        function<void(int)> dfs = [&](int i) {
            if (i == (int)digits.size()) {  // 递归终点：每一位都选好了，拼成完整组合
                res.push_back(path);
                return;
            }
            for (char ch : MAPPING[digits[i] - '0']) { // 当前数字对应的候选字母
                path.push_back(ch);         // 1. 做选择：选中字母 ch
                dfs(i + 1);                 // 2. 递归：去确定下一位
                path.pop_back();            // 3. 撤销选择：换下一个字母
            }
        };
        dfs(0);
        return res;
    }
};

