// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：数字串 digits（仅含 2-9；输入为空/空行表示空串）
// 输出格式：
//   第一行：组合总数
//   后续每行一个字母组合
#include <iostream>
#include <string>
#include <vector>
#include <functional>
using namespace std;

int main() {
    string digits;
    cin >> digits;                  // 空输入时提取失败，digits 保持空串
    const vector<string> MAPPING = {"", "", "abc", "def", "ghi",
                                    "jkl", "mno", "pqrs", "tuv", "wxyz"};
    vector<string> res;
    string path;
    function<void(int)> dfs = [&](int i) {
        if (i == (int)digits.size()) { // 每一位都确定了，收集组合
            res.push_back(path);
            return;
        }
        for (char ch : MAPPING[digits[i] - '0']) { // 当前数字的候选字母
            path.push_back(ch);        // 1. 做选择
            dfs(i + 1);                // 2. 递归确定下一位
            path.pop_back();           // 3. 撤销选择
        }
    };
    if (!digits.empty()) dfs(0);       // 空串直接输出 0，避免得到 [""]
    cout << res.size() << "\n";        // 第一行：组合总数
    for (const string& s : res) cout << s << "\n";
    return 0;
}

problems.codeJava:
class Solution {
    public List<String> letterCombinations(String digits) {
        List<String> res = new ArrayList<>();      // 存放所有字母组合
        if (digits.isEmpty()) return res;          // 边界：空输入返回空数组（而非 [""]）
        String[] MAPPING = {"", "", "abc", "def", "ghi",
                            "jkl", "mno", "pqrs", "tuv", "wxyz"};
        dfs(digits, MAPPING, 0, new StringBuilder(), res); // 回溯逐位枚举
        return res;
    }

    private void dfs(String digits, String[] mapping, int i,
                     StringBuilder path, List<String> res) {
        if (i == digits.length()) {                // 递归终点：每一位都选好了
            res.add(path.toString());
            return;
        }
        for (char ch : mapping[digits.charAt(i) - '0'].toCharArray()) { // 候选字母
            path.append(ch);                       // 1. 做选择：选中字母 ch
            dfs(digits, mapping, i + 1, path, res); // 2. 递归：去确定下一位
            path.deleteCharAt(path.length() - 1);  // 3. 撤销选择：换下一个字母
        }
    }
}

