func letterCombinations(digits string) []string {
	if digits == "" { // 边界：空输入返回空数组（而非 [""]）
		return []string{}
	}
	mapping := map[byte]string{
		'2': "abc", '3': "def", '4': "ghi", '5': "jkl",
		'6': "mno", '7': "pqrs", '8': "tuv", '9': "wxyz",
	}
	var res []string
	path := []byte{}
	var dfs func(i int)
	dfs = func(i int) {
		if i == len(digits) { // 递归终点：每一位都选好了
			res = append(res, string(path))
			return
		}
		for _, ch := range mapping[digits[i]] { // 当前数字对应的候选字母
			path = append(path, byte(ch))       // 1. 做选择：选中字母 ch
			dfs(i + 1)                          // 2. 递归：去确定下一位
			path = path[:len(path)-1]           // 3. 撤销选择：换下一个字母
		}
	}
	dfs(0)
	return res
}

problems.codeCpp:
class Solution {
public:
    vector<string> generateParenthesis(int n) {
        vector<string> res;              // 存放所有合法括号串
        string path;                     // 当前已构造的前缀
        // 回溯：left/right 分别是已使用的左、右括号数量
        function<void(int, int)> dfs = [&](int left, int right) {
            if ((int)path.size() == 2 * n) { // 递归终点：长度达到 2n，必然合法
                res.push_back(path);
                return;
            }
            if (left < n) {              // 剪枝 1：左括号没用完才能放 '('
                path.push_back('(');     // 1. 做选择：放一个左括号
                dfs(left + 1, right);    // 2. 递归：继续构造
                path.pop_back();         // 3. 撤销选择：回溯
            }
            if (right < left) {          // 剪枝 2：右括号数必须严格小于左括号数
                path.push_back(')');     // 1. 做选择：放一个右括号
                dfs(left, right + 1);    // 2. 递归：继续构造
                path.pop_back();         // 3. 撤销选择：回溯
            }
        };
        dfs(0, 0);
        return res;
    }
};

