// 输入格式：
//   第一行：n（括号对数）
// 输出格式：
//   第一行：方案数（第 n 个卡特兰数）
//   后续每行一个合法括号串（按回溯枚举顺序输出）
#include <iostream>
#include <string>
#include <vector>
#include <functional>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<string> res;
    string path;
    function<void(int, int)> dfs = [&](int left, int right) {
        if ((int)path.size() == 2 * n) { // 长度达到 2n，此时必然合法
            res.push_back(path);
            return;
        }
        if (left < n) {                  // 剪枝 1：左括号没用完才能放 '('
            path.push_back('(');
            dfs(left + 1, right);
            path.pop_back();
        }
        if (right < left) {              // 剪枝 2：右括号数必须严格小于左括号数
            path.push_back(')');
            dfs(left, right + 1);
            path.pop_back();
        }
    };
    dfs(0, 0);
    cout << res.size() << "\n";          // 第一行：方案数（卡特兰数）
    for (const string& s : res) cout << s << "\n";
