problems.codeCpp:
class Solution {
public:
    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        sort(candidates.begin(), candidates.end()); // 排序是剪枝的前提
        vector<vector<int>> res;
        vector<int> path;
        // 回溯：start 限制本层起点，rest 是距离 target 还差多少
        function<void(int, int)> dfs = [&](int start, int rest) {
            if (rest == 0) {            // 递归终点：恰好凑出 target，收集组合
                res.push_back(path);
                return;
            }
            for (int i = start; i < (int)candidates.size(); ++i) {
                int x = candidates[i];
                if (x > rest) break;    // 剪枝：x 已超标，后面只会更大，整层 break
                path.push_back(x);      // 1. 做选择：选 x（本题允许重复选）
                dfs(i, rest - x);       // 2. 递归：传 i 而非 i+1，下一层还能再选 x
                path.pop_back();        // 3. 撤销选择：回溯，尝试下一个候选数
            }
        };
        dfs(0, target);
        return res;
    }
};

problems.acmCodeCpp:
// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n（候选数个数）
//   第二行：n 个互不相同的整数（candidates）
//   第三行：target
// 输出格式：
//   第一行：方案数
//   后续每行一个组合（组合内数字升序，数字间空格分隔）
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int n, target;
vector<int> cands, path;
vector<vector<int>> res;

void dfs(int start, int rest) {
    if (rest == 0) {                    // 恰好凑出 target，收集组合
        res.push_back(path);
        return;
    }
    for (int i = start; i < n; ++i) {
        int x = cands[i];
        if (x > rest) break;            // 剪枝：后面只会更大，整层 break
        path.push_back(x);              // 1. 做选择（本题允许重复选）
        dfs(i, rest - x);               // 2. 递归传 i：下一层还能再选 x
        path.pop_back();                // 3. 撤销选择
    }
}

int main() {
    cin >> n;
    cands.resize(n);
    for (auto& x : cands) cin >> x;
    cin >> target;
    sort(cands.begin(), cands.end());   // 排序是剪枝的前提
    dfs(0, target);
    cout << res.size() << "\n";         // 第一行：方案数
    for (const auto& c : res) {
        for (int k = 0; k < (int)c.size(); ++k) {
            if (k) cout << ' ';
            cout << c[k];
        }
        cout << "\n";
    }
    return 0;
}

