class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        Arrays.sort(candidates);                        // 排序是剪枝的前提
        List<List<Integer>> res = new ArrayList<>();
        dfs(candidates, 0, target, new ArrayList<>(), res);
        return res;
    }

    // 回溯：start 限制本层起点，rest 是距离 target 还差多少
    private void dfs(int[] candidates, int start, int rest,
                     List<Integer> path, List<List<Integer>> res) {
        if (rest == 0) {                        // 递归终点：恰好凑出 target
            res.add(new ArrayList<>(path));
            return;
        }
        for (int i = start; i < candidates.length; i++) {
            int x = candidates[i];
            if (x > rest) break;                // 剪枝：x 已超标，后面只会更大
            path.add(x);                        // 1. 做选择：选 x（本题允许重复选）
            dfs(candidates, i, rest - x, path, res); // 2. 递归传 i：还能再选 x
            path.remove(path.size() - 1);       // 3. 撤销选择：回溯
        }
    }
}

