class Solution {
public:
    vector<vector<int>> combinationSum2(vector<int>& candidates, int target) {
        sort(candidates.begin(), candidates.end()); // 前置：排序让相同数字相邻
        vector<vector<int>> res;
        vector<int> path;
        function<void(int, int)> dfs = [&](int start, int rest) {
            if (rest == 0) {            // 递归终点：恰好凑出 target
                res.push_back(path);
                return;
            }
            for (int i = start; i < (int)candidates.size(); ++i) {
                int x = candidates[i];
                if (x > rest) break;    // 剪枝：本层后面只会更大，直接 break
                if (i > start && candidates[i] == candidates[i - 1])
                    continue;           // 同层去重：同值的不同下标，本层只允许选第一个
                path.push_back(x);      // 1. 做选择：选 x（每个数只能用一次）
                dfs(i + 1, rest - x);   // 2. 递归：传 i+1，不能再选自己
                path.pop_back();        // 3. 撤销选择：回溯
            }
        };
        dfs(0, target);
        return res;
    }
};

