    if (rest === 0) {                // 递归终点：恰好凑出 target
      res.push([...path]);
      return;
    }
    for (let i = start; i < candidates.length; i++) {
      const x = candidates[i];
      if (x > rest) break;           // 剪枝：本层后面只会更大，直接 break
      if (i > start && candidates[i] === candidates[i - 1])
        continue;                    // 同层去重：同值的不同下标只允许选第一个
      path.push(x);                  // 1. 做选择：选 x（每个数只能用一次）
      dfs(i + 1, rest - x);          // 2. 递归传 i+1：不能再选自己
      path.pop();                    // 3. 撤销选择：回溯
    }
  };
  dfs(0, target);
  return res;
