def solveNQueens_scan(n):
    res = []
    queens = []                    # queens[r]：第 r 行皇后列号

    def conflict(r, c):
        for r2, c2 in enumerate(queens):
            if c2 == c or abs(r - r2) == abs(c - c2):
                return True        # 同列或同一条斜线
        return False

    def dfs(r):
        if r == n:                 # n 行放好，拼出棋盘
            res.append(['.' * c + 'Q' + '.' * (n - 1 - c) for c in queens])
            return
        for c in range(n):
            if not conflict(r, c):
                queens.append(c)   # 1. 做选择：第 r 行放第 c 列
                dfs(r + 1)         # 2. 递归下一行
                queens.pop()       # 3. 撤销选择

    dfs(0)
    return res

