        vector<vector<string>> res;
        vector<int> queens(n, -1);        // queens[r] = c：第 r 行皇后放在第 c 列
        vector<bool> cols(n, false);      // 列占用标记
        vector<bool> diag1(2 * n, false); // 主对角线：r - c + n 相同即同一条斜线
        vector<bool> diag2(2 * n, false); // 副对角线：r + c 相同即同一条斜线
        function<void(int)> dfs = [&](int r) {
            if (r == n) {                 // 递归终点：n 行都放好，按列号拼出棋盘
                vector<string> board;
                for (int i = 0; i < n; ++i)
                    board.push_back(string(queens[i], '.') + 'Q' +
                                    string(n - 1 - queens[i], '.'));
                res.push_back(std::move(board));
                return;
            }
            for (int c = 0; c < n; ++c) {
                int d1 = r - c + n, d2 = r + c;
                if (cols[c] || diag1[d1] || diag2[d2])
                    continue;             // 剪枝：该列或两条斜线已被攻击，直接跳过
                cols[c] = diag1[d1] = diag2[d2] = true;
                queens[r] = c;            // 1. 做选择：第 r 行皇后放第 c 列
                dfs(r + 1);               // 2. 递归：处理下一行
                cols[c] = diag1[d1] = diag2[d2] = false;
                queens[r] = -1;           // 3. 撤销选择：释放全部标记
            }
        };
        dfs(0);
        return res;
    }
};

