	dfs = func(r int) {
		if r == n { // n 行都放好，按列号拼出棋盘
			board := make([]string, n)
			for i := 0; i < n; i++ {
				row := []byte{}
				for j := 0; j < n; j++ {
					if queens[i] == j {
						row = append(row, 'Q')
					} else {
						row = append(row, '.')
					}
				}
				board[i] = string(row)
			}
			res = append(res, board)
			return
		}
		for c := 0; c < n; c++ {
			d1, d2 := r-c+n, r+c
			if cols[c] || diag1[d1] || diag2[d2] {
				continue // 剪枝：该列或两条斜线已被攻击
			}
			cols[c], diag1[d1], diag2[d2] = true, true, true
			queens[r] = c // 1. 做选择：第 r 行皇后放第 c 列
			dfs(r + 1)    // 2. 递归：处理下一行
			cols[c], diag1[d1], diag2[d2] = false, false, false
			queens[r] = -1 // 3. 撤销选择：释放全部标记
		}
	}
	dfs(0)
	return res
}

