        function<void(int)> dfs = [&](int start) {
            if ((int)path.size() == k) { // 递归终点：凑够 k 个数
                res.push_back(path);
                return;
            }
            int need = k - (int)path.size(); // 还需要选多少个数
            // 剪枝：i 最大到 n - need + 1，再往后剩余候选凑不满 k 个
            for (int i = start; i <= n - need + 1; ++i) {
                path.push_back(i);       // 1. 做选择：把 i 加入组合
                dfs(i + 1);              // 2. 递归：只能从 i+1 往后选，防重复组合
                path.pop_back();         // 3. 撤销选择：回溯
            }
        };
        dfs(1);
        return res;
    }
};

