        return true;
    if (r < 0 || r >= m || c < 0 || c >= n || board[r][c] != word[i])
        return false;                   // 出界或当前字符不匹配
    board[r][c] = '#';                  // 1. 做选择：占用该格防止重复使用
    bool found = dfs(r + 1, c, i + 1) || dfs(r - 1, c, i + 1) ||
                 dfs(r, c + 1, i + 1) || dfs(r, c - 1, i + 1);
    board[r][c] = word[i];              // 3. 撤销选择：恢复现场
    return found;
}

