#include <vector>
#include <algorithm>
using namespace std;

int n;
vector<int> nums, path;
vector<vector<int>> res;

void dfs(int i) {
    res.push_back(path);                 // 子集型：进入每个节点先收集
    for (int j = i; j < n; ++j) {
        if (j > i && nums[j] == nums[j - 1])
            continue;                    // 同层去重：本层同值只允许选第一个
        path.push_back(nums[j]);         // 1. 做选择
        dfs(j + 1);                      // 2. 递归：只看 j 之后的元素
        path.pop_back();                 // 3. 撤销选择
    }
}

