class Solution:
    def partition(self, s: str) -> List[List[str]]:
        n = len(s)
        res, path = [], []

        def is_pal(lo: int, hi: int) -> bool:
            l, r = lo, hi           # 双指针从两端向中间收拢
            while l < r:
                if s[l] != s[r]:
                    return False
                l += 1
                r -= 1
            return True

        def dfs(start: int) -> None:
            # 递归终点：整个字符串都切成了回文段
            if start == n:
                res.append(path[:])
                return
            for end in range(start, n):
                if not is_pal(start, end):
                    continue        # 剪枝：s[start..end] 不是回文，跳过该切法
                path.append(s[start:end + 1])  # 1. 做选择：切出一段回文
                dfs(end + 1)                   # 2. 递归：分割剩余后缀
                path.pop()                     # 3. 撤销选择：回溯

        dfs(0)
        return res

