class Solution {
public:
    vector<vector<string>> partition(string s) {
        int n = s.size();
        vector<vector<string>> res;
        vector<string> path;
        auto isPal = [&](int lo, int hi) { // 双指针从两端向中间收拢判回文
            while (lo < hi) {
                if (s[lo] != s[hi]) return false;
                ++lo;
                --hi;
            }
            return true;
        };
        function<void(int)> dfs = [&](int start) {
            if (start == n) {            // 递归终点：整个字符串都切成了回文段
                res.push_back(path);
                return;
            }
            for (int end = start; end < n; ++end) {
                if (!isPal(start, end))  // 剪枝：s[start..end] 不是回文，跳过
                    continue;
                path.push_back(s.substr(start, end - start + 1)); // 1. 切出一段回文
                dfs(end + 1);            // 2. 递归：分割剩余后缀
                path.pop_back();         // 3. 撤销选择：回溯
            }
        };
        dfs(0);
        return res;
    }
};

