// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：字符串 s（仅小写字母）
// 输出格式：
//   第一行：方案数
//   后续每行一个分割方案，各回文段之间用空格分隔
#include <iostream>
#include <string>
#include <vector>
using namespace std;

string s;
vector<string> path;
vector<vector<string>> res;

bool isPal(int lo, int hi) {             // 双指针判回文
    while (lo < hi) {
        if (s[lo] != s[hi]) return false;
        ++lo;
        --hi;
    }
    return true;
}

void dfs(int start) {
    if (start == (int)s.size()) {        // 整串切完，收集方案
        res.push_back(path);
        return;
    }
    for (int end = start; end < (int)s.size(); ++end) {
        if (!isPal(start, end))
            continue;                    // 剪枝：该前缀不是回文
        path.push_back(s.substr(start, end - start + 1)); // 1. 做选择：切出一段回文
        dfs(end + 1);                    // 2. 递归：分割剩余后缀
        path.pop_back();                 // 3. 撤销选择
    }
}

int main() {
    cin >> s;
    dfs(0);
    cout << res.size() << "\n";          // 第一行：方案数
    for (const auto& plan : res) {
        for (int k = 0; k < (int)plan.size(); ++k) {
            if (k) cout << ' ';
            cout << plan[k];
        }
        cout << "\n";
    }
    return 0;
}

