class Solution {
    public List<List<String>> partition(String s) {
        List<List<String>> res = new ArrayList<>();
        dfs(s, 0, new ArrayList<>(), res);
        return res;
    }

    private void dfs(String s, int start, List<String> path, List<List<String>> res) {
        int n = s.length();
        if (start == n) {                      // 递归终点：整串切完，收集方案
            res.add(new ArrayList<>(path));
            return;
        }
        for (int end = start; end < n; end++) {
            if (!isPal(s, start, end))         // 剪枝：该前缀不是回文，跳过
                continue;
            path.add(s.substring(start, end + 1)); // 1. 做选择：切出一段回文
            dfs(s, end + 1, path, res);        // 2. 递归：分割剩余后缀
            path.remove(path.size() - 1);      // 3. 撤销选择：回溯
        }
    }

    private boolean isPal(String s, int lo, int hi) { // 双指针判回文
        while (lo < hi) {
            if (s.charAt(lo) != s.charAt(hi)) return false;
            lo++;
            hi--;
        }
        return true;
    }
}

